mapper.select:
SELECT snapshot_id, ref FROM (
    SELECT n.snapshot_id, n.ref
    FROM asset_structure_nodes n
    WHERE n.snapshot_id IN
    #{sid}
    UNION ALL
    SELECT a.snapshot_id, a.asset_ref AS ref
    FROM asset_structured_assets a
    WHERE a.snapshot_id IN
    #{sid}
) u
LIMIT #{limit}

SELECT n.snapshot_id, n.ref
FROM asset_structure_nodes n
WHERE n.node_type = 'document'
  AND n.snapshot_id IN
#{sid}
LIMIT #{limit}

SELECT u.snapshot_id, u.canonical_evidence_id AS ref
FROM (
    SELECT DISTINCT r.snapshot_id, r.canonical_evidence_id
    FROM asset_retrieval_units_v2 r
    WHERE r.snapshot_id IN
    #{sid}
) u
LIMIT #{limit}

SELECT DISTINCT bs.document_snapshot_id AS snapshot_id, bs.document_snapshot_id AS ref
FROM asset_build_document_snapshots bs
JOIN asset_builds    b ON b.id = bs.build_id
JOIN asset_documents d ON d.id = bs.document_id
WHERE b.kb_id = d.kb_id
  AND d.deleted_at IS NULL
  AND d.domain = #{domain}
  AND d.kb_id IN
#{kbId}
LIMIT #{limit}

SELECT snapshot_id, node_type, ref, parent_ref, ordinal, title, level, block_type
FROM asset_structure_nodes
WHERE snapshot_id = #{snapshotId} AND ref = #{ref}

SELECT snapshot_id, node_type, ref, parent_ref, ordinal, title, level, block_type
FROM asset_structure_nodes
WHERE snapshot_id = #{snapshotId} AND parent_ref = #{parentRef}
ORDER BY ordinal ASC NULLS LAST, ref ASC
LIMIT #{limit} OFFSET #{offset}

SELECT snapshot_id, node_type, ref, parent_ref, ordinal, title, level, block_type
FROM asset_structure_nodes
WHERE snapshot_id = #{snapshotId} AND parent_ref = #{parentRef}
ORDER BY ordinal ASC NULLS LAST, ref ASC
LIMIT #{limit}

SELECT snapshot_id, relation, from_ref, to_ref
FROM asset_structure_edges
WHERE snapshot_id = #{snapshotId} AND from_ref = #{fromRef} AND relation = #{relation}
LIMIT #{limit}

SELECT snapshot_id, asset_ref, asset_type, table_ref,
       columns_json::text AS columns_json, row_count, readiness, schema_version
FROM asset_structured_assets
WHERE snapshot_id = #{snapshotId}
ORDER BY asset_ref ASC
LIMIT #{limit}

SELECT snapshot_id, table_ref, row_index, column_index, column_name, value, is_header
FROM asset_table_cells
WHERE snapshot_id = #{snapshotId} AND table_ref = #{tableRef}
ORDER BY is_header DESC, row_index ASC, column_index ASC
LIMIT #{limit}
